assert set(ids) == set(PREDS), "case set mismatch"
written = 0
for cid in ids:
    p = PREDS[cid]
    doc = {"case_id": cid, "prediction_text": p["prediction_text"], "basis": p["basis"],
           "confidence": p["confidence"], "trigger": p["trigger"]}
    assert set(doc) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(doc["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
    assert 0 <= doc["confidence"] <= 1
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(doc, f, ensure_ascii=False, indent=1)
    written += 1
# 回读自验
ok = 0
for cid in ids:
    with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid and set(d) == {"case_id","prediction_text","basis","confidence","trigger"}
    ok += 1
assert written == len(ids) == 20 and ok == 20
cm = sum(PREDS[c]["trigger"]["changed_main"] for c in ids)
ru = sum(PREDS[c]["trigger"]["reserve_used"] for c in ids)
dp = sum(PREDS[c]["trigger"]["disputed"] for c in ids)
print(f"batch=20 written={written} parsed_ok={ok} changed_main={cm} reserve_used={ru} disputed={dp}")
